1	// PearlOS error feedback intake.
2	// Frontend (ErrorBoundary, global error handler) POSTs errors here.
3	// Server logs + fans out to team Discord webhook if DISCORD_ERROR_WEBHOOK is set.
4	//
5	// ENV:
6	//   DISCORD_ERROR_WEBHOOK  - Discord channel webhook URL (dev team error feed)
7	//
8	// Intentional: no auth requirement (errors must report even from logged-out crashes),
9	// but we rate-limit by IP in-memory and redact obvious secrets.
10	
11	import { NextRequest, NextResponse } from "next/server";
12	import { getLogger } from "@interface/lib/logger";
13	
14	export const dynamic = "force-dynamic";
15	export const runtime = "nodejs";
16	
17	const log = getLogger("[api_report_error]");
18	
19	// Simple in-memory token bucket per IP. Survives hot reload within one process.
20	type Bucket = { tokens: number; last: number };
21	const RATE_LIMIT_MAX = 20;          // max reports per window
22	const RATE_LIMIT_WINDOW_MS = 60_000; // 1 minute
23	const buckets = new Map<string, Bucket>();
24	
25	function allow(ip: string): boolean {
26	  const now = Date.now();
